def copy_tree_to(host: str, local_dir: Path, remote_dir: str, timeout_s: int) -> dict[str, Any]:
  return iq36_local.copy_tree_to(host, local_dir, remote_dir, timeout_s)


def build_command(remote_dir: str, env_script: str) -> str:
  return " && ".join([
      f"source {shlex.quote(env_script)} >/dev/null 2>&1",
      "g++ -std=c++17 -O2 -Wall -Wextra -Wpedantic "
      f"-I {shlex.quote(remote_dir + '/include')} "
      f"{shlex.quote(remote_dir + '/src/gguf_loader.cpp')} "
      f"{shlex.quote(remote_dir + '/src/gpu_q4_cpu_order_matvec.cpp')} "
      f"{shlex.quote(remote_dir + '/src/gpu_q4x8_matvec.cpp')} "
      f"{shlex.quote(remote_dir + '/src/resident_harness.cpp')} "
      f"{shlex.quote(remote_dir + '/tests/r2_gpu_decode_smoke.cpp')} "
      "-ldl -pthread "
      f"-o {shlex.quote(remote_dir + '/build/r2-gpu-decode-smoke')}",
  ])


def run_command(args: argparse.Namespace, remote_dir: str, remote_token_dir: str,
                exe: str | None = None) -> str:
  exe = exe or (remote_dir + "/build/r2-gpu-decode-smoke")
  parts = [
      shlex.quote(exe),
      "--model", shlex.quote(args.model),
      "--token-dir", shlex.quote(remote_token_dir),
      "--case-id", shlex.quote(args.case_id),
      "--device-substring", shlex.quote(args.device_substring),
      "--repeat", str(args.repeat),
      "--decode-tokens", str(args.decode_tokens),
      "--lm-head-threads", str(args.lm_head_threads),
  ]
  if args.resident_session_repeats != 1:
    parts.extend(["--resident-session-repeats", str(args.resident_session_repeats)])
  if args.shared_q4_runner:
    parts.append("--shared-q4-runner")
  if args.resident_q4_weights:
    parts.append("--resident-q4-weights")
  if args.resident_selected_q4_experts:
    parts.append("--resident-selected-q4-experts")
  if args.resident_selected_q6_experts:
    parts.append("--resident-selected-q6-experts")
  if args.resident_selected_q6_sorted_cache:
    parts.append("--resident-selected-q6-sorted-cache")
  if args.resident_selected_q6_rowstripe:
    parts.append("--resident-selected-q6-rowstripe")
  if args.resident_selected_cache_topk != 8:
    parts.extend(["--resident-selected-cache-topk", str(args.resident_selected_cache_topk)])
  if args.gpu_live_selected_cache_prewarm:
    parts.append("--gpu-live-selected-cache-prewarm")
  if args.resident_shared_q6_down:
    parts.append("--resident-shared-q6-down")
  if args.resident_full_attention_v_q6:
    parts.append("--resident-full-attention-v-q6")
  if args.resident_linear_q6_qkv:
    parts.append("--resident-linear-q6-qkv")
  if args.linear_preconv_shared_q8:
    parts.append("--linear-preconv-shared-q8")
  if args.resident_q4_cpu_order_z:
    parts.append("--resident-q4-cpu-order-z")
  if args.resident_q4_cpu_order_linear_ab:
    parts.append("--resident-q4-cpu-order-linear-ab")
  if args.resident_linear_conv_weights:
    parts.append("--resident-linear-conv-weights")
  if args.resident_linear_state:
    parts.append("--resident-linear-state")
  if args.resident_postconv_delta_handoff:
    parts.append("--resident-postconv-delta-handoff")
  if args.sync_resident_linear_state_host:
    parts.append("--sync-resident-linear-state-host")
  if args.resident_norm_weights:
    parts.append("--resident-norm-weights")
  if args.resident_tail_output_rmsnorm_input:
    parts.append("--resident-tail-output-rmsnorm-input")
  if args.resident_gate_up_swiglu_handoff:
    parts.append("--resident-gate-up-swiglu-handoff")
  if args.resident_swiglu_q6_down_handoff:
    parts.append("--resident-swiglu-q6-down-handoff")
  if args.resident_shared_swiglu_q6_down_handoff:
    parts.append("--resident-shared-swiglu-q6-down-handoff")
  if args.resident_attention_front_handoff:
    parts.append("--resident-attention-front-handoff")
  if args.resident_full_core_attention_front_handoff:
    parts.append("--resident-full-core-attention-front-handoff")
  if args.resident_full_core_attention_front_handoff_exclude_layers:
    parts.extend([
        "--resident-full-core-attention-front-handoff-exclude-layers",
        shlex.quote(args.resident_full_core_attention_front_handoff_exclude_layers),
    ])
  if args.resident_full_core_attention_front_handoff_extrapolate_layers:
    parts.extend([
        "--resident-full-core-attention-front-handoff-extrapolate-layers",
        shlex.quote(args.resident_full_core_attention_front_handoff_extrapolate_layers),
        "--resident-full-core-attention-front-handoff-extrapolate-gain",
        str(args.resident_full_core_attention_front_handoff_extrapolate_gain),
    ])
